<!doctype html>
<html><head><meta charset="utf-8"><title>{{ $incident->reference }}</title><style>body{font:14px Arial;color:#17212b;margin:40px}h1{color:#0e5963;border-bottom:2px solid #2dd4bf;padding-bottom:10px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccd6d8;padding:9px;text-align:left;vertical-align:top}th{background:#edf5f5;width:30%}</style></head><body><h1>Form DP3 incident record</h1><table><tr><th>Reference</th><td>{{ $incident->reference }}</td></tr><tr><th>Title</th><td>{{ $incident->title }}</td></tr><tr><th>Status</th><td>{{ ucfirst($incident->status) }}</td></tr><tr><th>Severity</th><td>{{ ucfirst($incident->severity) }}</td></tr><tr><th>Occurred at</th><td>{{ $incident->occurred_at->format('d M Y, H:i') }}</td></tr><tr><th>Detected at</th><td>{{ $incident->detected_at->format('d M Y, H:i') }}</td></tr><tr><th>DP3 deadline</th><td>{{ $incident->sla_due_at->format('d M Y, H:i') }}</td></tr><tr><th>Description</th><td>{{ $incident->description }}</td></tr><tr><th>Affected data subjects</th><td>{{ implode(', ', $incident->affected_data_subjects ?? []) }}</td></tr></table></body></html>
